const employment = ctx.subject.employment;
const terms = employment.terms;
const partTime = get(employment, 'engagement', 'EMPLOYEE') === 'PART_TIME';
const normal = Number(
	get(
		terms,
		'normal_hours_per_day',
		partTime
			? ctx.lookup.part_time_hours_factor * 8
			: 8
	)
);
const orpDay = ctx.day_rate;
const days = get(ctx, 'work.days', []);
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const worked = days.filter(
	(day) => holiday(day) && Math.min(Number(get(day, 'worked_hours', 0)), normal) > 0
);
// s.60D(3)(a): two days' wages at the ordinary rate of pay for a holiday worked, however short the work. An employer
// with its own hour (pay_methods CONTRACT_WEEKLY) prices the shift hours it clocked at that multiple of the hour, as a
// pre-approved payroll vendor computes it: the owner's decision of 2026-11-12, not floored at the Act's two days.
const own = get(ctx.subject.employer, 'pay_methods.overtime_hour_basis', 'STATUTORY') === 'CONTRACT_WEEKLY';
return worked.reduce((total, day) => {
	if (!own) return total + ctx.lookup.holiday_work_days * orpDay;
	const hours = Math.min(Number(get(day, 'clocked_shift_hours', 0)), normal);
	const method = round(hours * ctx.lookup.holiday_work_days * ctx.hour_rate, ctx.lookup.minor_unit, 'HALF_UP');
	return total + method;
}, 0);

